sections.css:
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0f172a;color:#e2e8f0;font-family:'Segoe UI',Tahoma,sans-serif;display:flex;justify-content:center;padding:8px}
.container{max-width:680px;width:100%}
h1{text-align:center;font-size:14px;color:#fbbf24;margin-bottom:4px}
canvas{background:#0f172a;border:1px solid #334155;border-radius:8px;display:block;margin:0 auto;width:100%;max-width:660px;height:420px}
.controls{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-top:6px;background:#1e293b;border-radius:6px;padding:8px;border:1px solid #334155}
.ctrl-group{display:flex;flex-direction:column;gap:2px}
.ctrl-group label{font-size:10px;color:#94a3b8}
.ctrl-group .val{color:#fbbf24;font-size:12px;font-weight:700}
input[type=range]{width:100%;height:4px;-webkit-appearance:none;background:#334155;border-radius:2px;outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:#f59e0b;cursor:pointer}
.btn{background:#334155;color:#94a3b8;border:1px solid #475569;border-radius:4px;padding:4px 8px;font-size:10px;cursor:pointer;text-align:center;transition:all .15s}
.btn.active{background:#3b82f6;color:#fff;border-color:#3b82f6;font-weight:700}
.btn:hover{background:#475569;color:#e2e8f0}
.speed-btn{flex:1;padding:3px 4px;font-size:9px;min-width:0}
.nernst{text-align:center;margin-top:4px;background:#1e293b;border-radius:6px;padding:5px 8px;border:1px solid #334155}
.nernst-label{display:block;font-size:9px;color:#64748b;margin-bottom:2px}
.nernst-val{display:block;font-size:11px;color:#38bdf8;font-weight:700;direction:ltr}
.stats{display:flex;gap:8px;justify-content:center;margin-top:4px;font-size:11px;color:#94a3b8;flex-wrap:wrap}
.stats span{background:#1e293b;padding:3px 8px;border-radius:4px;border:1px solid #334155}
.stats .big{font-size:13px;font-weight:700}
.stats .v{color:#22c55e}
.stats .e{color:#38bdf8}
.stats .i{color:#f59e0b}

