var c=document.getElementById('c'),ctx=c.getContext('2d');
var W=660,H=420;

var logCu=-1,logZn=-1,playing=false,massCu=0,time=0,animSpeed=100;
var E0Cu=0.34,E0Zn=-0.76;
var eOffset=0,ionOffset=0;
var emfHistory=[];

var bx1=30,by1=50,bw1=180,bh1=220;
var bx2=W-210,by2=50,bw2=180,bh2=220;
var wireY=by1-22;

function calcEMF(){return E0Cu+0.03*Math.log10(Math.pow(10,logCu))-(E0Zn+0.03*Math.log10(Math.pow(10,logZn)))}

function draw(){ctx.clearRect(0,0,W,H);
ctx.fillStyle='#0f172a';ctx.fillRect(0,0,W,H);

var cuConc=Math.pow(10,logCu),znConc=Math.pow(10,logZn);
var emf=calcEMF();
var loadX=(bx1+bw1+bx2)/2;

// Wire
ctx.strokeStyle='#fbbf24';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(bx1+bw1/2,wireY);ctx.lineTo(bx2+bw2/2,wireY);ctx.stroke();

// Conventional current arrow (I ← opposite to electrons)
ctx.fillStyle='#22c55e';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';
if(emf>0)ctx.fillText('I ←',bx2+bw2/2-25,wireY-14);
else ctx.fillText('I = 0',bx2+bw2/2-25,wireY-14);

// Resistor load
ctx.strokeStyle='#f59e0b';ctx.lineWidth=2;ctx.beginPath();
var zigzag=[[loadX-22,wireY],[loadX-16,wireY-8],[loadX-8,wireY+8],[loadX,wireY-8],[loadX+8,wireY+8],[loadX+16,wireY-8],[loadX+22,wireY]];
ctx.moveTo(zigzag[0][0],zigzag[0][1]);
for(var i=1;i<zigzag.length;i++)ctx.lineTo(zigzag[i][0],zigzag[i][1]);
ctx.stroke();
ctx.fillStyle='#f59e0b';ctx.font='7px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('R',loadX,wireY+18);

// Voltage meter + EMF bar
var mx=loadX,my=wireY-32;
ctx.fillStyle='#1e293b';ctx.strokeStyle='#475569';ctx.lineWidth=1;ctx.fillRect(mx-38,my-10,80,20);ctx.strokeRect(mx-38,my-10,80,20);
ctx.fillStyle='#38bdf8';ctx.font='bold 11px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('E = '+emf.toFixed(3)+' V',mx,my+4);
// EMF bar
var emfPct=Math.min(1,Math.max(0,(emf-0.5)/0.7));
ctx.fillStyle='#334155';ctx.fillRect(mx+44,my-6,28,12);
ctx.fillStyle=emf>1.0?'#22c55e':emf>0.5?'#f59e0b':'#ef4444';
ctx.fillRect(mx+44,my-6,28*emfPct,12);

// Nernst equation text
ctx.fillStyle='#64748b';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';
ctx.fillText('E = E°(Cu²⁺/Cu) − E°(Zn²⁺/Zn) + (0.06/2)·log([Cu²⁺]/[Zn²⁺])',W/2,by1-42);
ctx.fillStyle='#38bdf8';ctx.font='8px "Segoe UI",Tahoma,sans-serif';
var nernstStr='E = '+E0Cu.toFixed(2)+' − ('+E0Zn.toFixed(2)+') + 0.03·log('+cuConc.toFixed(2)+'/'+znConc.toFixed(2)+') = '+emf.toFixed(3)+' V';
ctx.fillText(nernstStr,W/2,by1-32);

// Electron flow
if(emf>0){eOffset+=0.6;
for(var i=0;i<6;i++){var xPos=((eOffset+i*14)%(bx2+bw2/2-bx1-bw1/2+30))-15;
var ex=bx1+bw1/2+xPos;
if(ex>=bx1+bw1/2&&ex<=bx2+bw2/2){if(ex>loadX-24&&ex<loadX+24)continue;
ctx.fillStyle=i<3?'#fbbf24':'rgba(251,191,36,0.35)';
ctx.beginPath();ctx.arc(ex,wireY,i<3?3:2,0,Math.PI*2);ctx.fill()}}
ctx.fillStyle='#fbbf24';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('e⁻ →',bx1+bw1/2+25,wireY-14)
}else{ctx.fillStyle='#64748b';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('e⁻ →',bx1+bw1/2+25,wireY-14)}

// Left beaker (Zn)
ctx.strokeStyle='#475569';ctx.lineWidth=2;ctx.strokeRect(bx1,by1,bw1,bh1);
var znH=Math.max(20,Math.min(Math.abs(logZn)*50+15,bh1-20));
var znAlpha=Math.min(0.2,znConc*0.5+0.05);
ctx.fillStyle='rgba(148,163,184,'+znAlpha+')';ctx.fillRect(bx1+6,by1+bh1-znH-6,bw1-12,znH);
ctx.fillStyle='#94a3b8';ctx.font='9px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('ZnSO₄ ['+znConc.toFixed(2)+' M]',bx1+bw1/2,by1+bh1+14);

// Zn electrode
var znHt=bh1+12-massCu*0.3;if(znHt<30)znHt=30;
ctx.fillStyle='#94a3b8';ctx.fillRect(bx1+bw1/2-8,by1-8,16,znHt);
ctx.fillStyle='#cbd5e1';ctx.fillRect(bx1+bw1/2-5,by1-6,10,znHt-4);
ctx.fillStyle='#e2e8f0';ctx.font='10px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('Zn (−)',bx1+bw1/2,by1-16);
ctx.fillStyle='#f87171';ctx.font='9px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('مصعد (Anode)',bx1+bw1/2,by1+bh1+28);

// Right beaker (Cu)
ctx.strokeStyle='#475569';ctx.lineWidth=2;ctx.strokeRect(bx2,by2,bw2,bh2);
var cuH=Math.max(20,Math.min(Math.abs(logCu)*50+15,bh1-20));
var cuAlpha=Math.min(0.35,cuConc*0.8+0.05);
ctx.fillStyle='rgba(59,130,246,'+cuAlpha+')';ctx.fillRect(bx2+6,by2+bh2-cuH-6,bw2-12,cuH);
ctx.fillStyle='#94a3b8';ctx.font='9px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('CuSO₄ ['+cuConc.toFixed(2)+' M]',bx2+bw2/2,by2+bh2+14);

// Cu electrode
ctx.fillStyle='#d97706';ctx.fillRect(bx2+bw2/2-8,by2-8,16,30);
ctx.fillStyle='#f59e0b';ctx.fillRect(bx2+bw2/2-5,by2-6,10,28);
var cuDep=massCu*1.5;if(cuDep>bh1-10)cuDep=bh1-10;
if(cuDep>0){ctx.fillStyle='#b45309';ctx.fillRect(bx2+bw2/2-8,by2+22,16,cuDep);
ctx.fillStyle='#d97706';ctx.fillRect(bx2+bw2/2-5,by2+24,10,cuDep-2)}
ctx.fillStyle='#fbbf24';ctx.font='10px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('Cu (+)',bx2+bw2/2,by2-16);
ctx.fillStyle='#22c55e';ctx.font='9px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('مهبط (Cathode)',bx2+bw2/2,by2+bh1+28);

// Salt bridge
var sbx1=bx1+bw1+10,sbx2=bx2-10,sby=by1+75,sbh=90;
ctx.strokeStyle='#64748b';ctx.lineWidth=2;ctx.setLineDash([4,4]);
ctx.beginPath();ctx.moveTo(sbx1,sby);ctx.lineTo(sbx1,sby+sbh);ctx.lineTo(sbx2,sby+sbh);ctx.lineTo(sbx2,sby);ctx.stroke();ctx.setLineDash([]);
ctx.fillStyle='#94a3b8';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('جسر ملحي',(sbx1+sbx2)/2,sby+sbh+12);

// Ion animation in salt bridge
if(playing&&emf>0){ionOffset+=0.5;
for(var i=0;i<3;i++){var kx=sbx1+((ionOffset+i*30)%(sbx2-sbx1));
ctx.fillStyle='rgba(168,85,247,0.8)';ctx.beginPath();ctx.arc(kx,sby+12+i*25,3,0,Math.PI*2);ctx.fill();
ctx.fillStyle='rgba(168,85,247,0.5)';ctx.font='6px "Segoe UI",Tahoma,sans-serif';ctx.fillText('K⁺',kx+6,sby+12+i*25+2)}
for(var i=0;i<3;i++){var clx=sbx2-((ionOffset+i*30)%(sbx2-sbx1));
ctx.fillStyle='rgba(34,197,94,0.8)';ctx.beginPath();ctx.arc(clx,sby+30+i*25,3,0,Math.PI*2);ctx.fill();
ctx.fillStyle='rgba(34,197,94,0.5)';ctx.font='6px "Segoe UI",Tahoma,sans-serif';ctx.fillText('Cl⁻',clx-8,sby+30+i*25+2)}}

// Reaction equations
var eqY=by1+bh1+36;
ctx.fillStyle='#94a3b8';ctx.font='10px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='right';ctx.fillText('مصعد (−): Zn → Zn²⁺ + 2e⁻',W-12,eqY);
ctx.textAlign='left';ctx.fillText('مهبط (+): Cu²⁺ + 2e⁻ → Cu',12,eqY);
ctx.fillStyle='#fbbf24';ctx.font='10px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('Zn + Cu²⁺ → Zn²⁺ + Cu',W/2,eqY+14);

// EMF vs time graph
var gx=40,gy=by1+bh1+55,gw2=W-80,gh2=90;
ctx.fillStyle='#1e293b';ctx.fillRect(gx,gy,gw2,gh2);
ctx.strokeStyle='#334155';ctx.lineWidth=1;ctx.strokeRect(gx,gy,gw2,gh2);
// Title
ctx.fillStyle='#64748b';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='center';ctx.fillText('تطور القوة المحركة الكهربائية مع الزمن',gx+gw2/2,gy+12);
ctx.fillStyle='#475569';ctx.font='7px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='left';ctx.fillText('E (V)',gx+4,gy+24);
ctx.textAlign='right';ctx.fillText('t (s)',gx+gw2-4,gy+gh2-4);
// Grid lines
ctx.strokeStyle='rgba(71,85,105,0.4)';ctx.lineWidth=0.5;
for(var i=0;i<4;i++){var gy2=gy+25+(i/4)*(gh2-35);ctx.beginPath();ctx.moveTo(gx+5,gy2);ctx.lineTo(gx+gw2-5,gy2);ctx.stroke()}
// EMF line
if(emfHistory.length>1){
var minE=Math.min.apply(null,emfHistory);var maxE=Math.max.apply(null,emfHistory);var er=Math.max(0.001,maxE-minE);
ctx.strokeStyle='#38bdf8';ctx.lineWidth=1.5;ctx.beginPath();
for(var i=0;i<emfHistory.length;i++){var ex2=gx+5+(i/(emfHistory.length-1))*(gw2-10);
var ey2=gy+25+((maxE-emfHistory[i])/er)*(gh2-35);
if(i===0)ctx.moveTo(ex2,ey2);else ctx.lineTo(ex2,ey2)}
ctx.stroke()}
// Current values
ctx.fillStyle='#38bdf8';ctx.font='bold 9px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='left';ctx.fillText('E = '+emf.toFixed(3)+' V',gx+6,gy+gh2-6);
ctx.fillStyle='#94a3b8';ctx.font='8px "Segoe UI",Tahoma,sans-serif';ctx.textAlign='right';ctx.fillText('t = '+time.toFixed(1)+' s',gx+gw2-6,gy+gh2-6);

// Update DOM
document.getElementById('emfDisplay').textContent='E = '+emf.toFixed(3)+' V';
document.getElementById('currentDisplay').textContent='I = '+(emf>0?(emf*0.5).toFixed(1):0)+' mA';
document.getElementById('massDisplay').textContent=massCu.toFixed(2)+' mg';
document.getElementById('nernstDisplay').textContent='E = '+E0Cu.toFixed(2)+' − ('+E0Zn.toFixed(2)+') + 0.03·log('+cuConc.toFixed(2)+'/'+znConc.toFixed(2)+') = '+emf.toFixed(3)+' V';
}

// Event listeners
document.getElementById('cuSlider').addEventListener('input',function(){logCu=parseFloat(this.value);document.getElementById('cuLabel').textContent=Math.pow(10,logCu).toFixed(2)+' M';draw()});
document.getElementById('znSlider').addEventListener('input',function(){logZn=parseFloat(this.value);document.getElementById('znLabel').textContent=Math.pow(10,logZn).toFixed(2)+' M';draw()});

document.querySelectorAll('.speed-btn').forEach(function(b){b.addEventListener('click',function(){if(playing){playing=false;document.getElementById('btnPlay').textContent='▶ تشغيل'}
document.querySelectorAll('.speed-btn').forEach(function(x){x.classList.remove('active')});this.classList.add('active');
animSpeed=parseInt(this.dataset.speed);
var labels={200:'بطيء',100:'عادية',40:'سريع'};document.getElementById('speedLabel').textContent=labels[animSpeed]})});

document.getElementById('btnPlay').addEventListener('click',function(){playing=!playing;this.textContent=playing?'⏸ إيقاف':'▶ تشغيل';if(playing)animate()});
document.getElementById('btnReset').addEventListener('click',function(){playing=false;massCu=0;time=0;eOffset=0;ionOffset=0;emfHistory=[];logCu=-1;logZn=-1;document.getElementById('cuSlider').value=-1;document.getElementById('znSlider').value=-1;document.getElementById('cuLabel').textContent='0.10 M';document.getElementById('znLabel').textContent='0.10 M';document.getElementById('btnPlay').textContent='▶ تشغيل';draw()});

function animate(){if(!playing)return;var emf=calcEMF();if(emf>0){time+=0.1;massCu+=emf*0.05;var delta=emf*0.003;logCu=Math.max(-2,logCu-delta*0.5);logZn=Math.min(0,logZn+delta*0.5);document.getElementById('cuSlider').value=logCu;document.getElementById('znSlider').value=logZn;document.getElementById('cuLabel').textContent=Math.pow(10,logCu).toFixed(2)+' M';document.getElementById('znLabel').textContent=Math.pow(10,logZn).toFixed(2)+' M'}
if(emfHistory.length>120)emfHistory.shift();emfHistory.push(emf);draw();setTimeout(animate,animSpeed)}

draw();
